<?php
require_once __DIR__.'/includes/functions.php';require_role(['student']);$pageTitle='My borrowing';$s=db()->prepare("SELECT i.*,b.title,b.author,b.cover_image,f.amount,f.paid_amount FROM issues i JOIN books b ON b.id=i.book_id LEFT JOIN fines f ON f.issue_id=i.id WHERE i.user_id=? ORDER BY i.issue_date DESC");$s->execute([current_user()['id']]);$loans=$s->fetchAll();require __DIR__.'/includes/header.php';
?>
<div class="mb-4"><p class="text-primary small text-uppercase fw-bold mb-1">My library</p><h1 class="page-title mb-1">Borrowing history</h1><p class="muted mb-0">Keep track of due dates, returns, and fines.</p></div><div class="table-wrap"><table class="table"><thead><tr><th>Book</th><th>Issue date</th><th>Due date</th><th>Returned</th><th>Status</th><th>Fine</th></tr></thead><tbody><?php foreach($loans as $l):$fine=(float)($l['amount']??0);$paid=(float)($l['paid_amount']??0);if($l['status']==='issued'&&$l['due_date']<date('Y-m-d'))$fine=max($fine,fine_for($l['due_date'])); ?><tr><td><strong><?=e($l['title'])?></strong><div class="small muted"><?=e($l['author'])?></div></td><td><?=e($l['issue_date'])?></td><td><?=e($l['due_date'])?></td><td><?=e($l['return_date']??'—')?></td><td><span class="badge-soft <?=$l['status']==='issued'&&$l['due_date']<date('Y-m-d')?'badge-unavailable':'badge-available'?>"><?=e($l['status']==='returned'?'Returned':($l['due_date']<date('Y-m-d')?'Overdue':'Issued'))?></span></td><td><?=money(max(0,$fine-$paid))?></td></tr><?php endforeach; ?></tbody></table><?php if(!$loans): ?><div class="empty-state"><i class="bi bi-clock-history d-block mb-2"></i><h5>No borrowing history yet</h5><a href="catalog.php">Explore books</a></div><?php endif; ?></div>
<?php require __DIR__.'/includes/footer.php'; ?>
